package review

import (
	"html/template"
	"io"
)

var report = template.Must(template.New("report").Parse(`<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>sentient1 incident report</title>
<style>body{margin:0;background:#0c1420;color:#e3eaf5;font:15px/1.6 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:42px 28px}h1{font-size:38px;margin:0;color:#68c7ff}h2{margin-top:32px}h3{margin:0 0 12px}.sub,small{color:#a1b4cc}.card{background:#142237;border:1px solid #293e56;border-radius:12px;padding:22px;margin:18px 0}.badge{display:inline-block;background:#213b55;padding:3px 12px;border-radius:16px}td,th{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid #304156}table{width:100%;border-collapse:collapse}code,pre{overflow-wrap:anywhere;white-space:pre-wrap}.critical{border-left:4px solid #ff7676}.warn{border-left:4px solid #ffd27c}.info{border-left:4px solid #68c7ff}ul{padding-left:22px}@media print{body{background:white;color:#111}.card{background:white;border-color:#777}h1,small,.sub{color:#333}}</style>
<main><h1>sentient1</h1><p class="sub">Incident &amp; coverage report · {{.Version}} · {{.Generated.Format "2006-01-02 15:04:05 MST"}}</p>
<div class="card"><h2>{{.Assessment.Title}}</h2><p>Service: {{.Service}} · Policy: {{.Policy}} · Decoys: {{.Assessment.Healthy}} / {{.Assessment.Total}} · Active response records: {{.Assessment.ActiveResponses}}</p><ul>{{range .Assessment.Reasons}}<li>{{.}}</li>{{end}}{{range .Problems}}<li>{{.}}</li>{{end}}</ul><p>Reader identification: {{if .Instant}}audit events plus optional timing-based oplock inference{{else}}Windows Security audit events{{end}}.</p></div>
<p class="sub">A decoy tripwire detects access to monitored files. It cannot guarantee detection of all trojans, prevent every upload, or replace antivirus. A detection needs investigation; legitimate backup and sync applications can trigger it. {{if not .CommandLinesIncluded}}Command lines have been excluded from this export.{{end}} Local paths and network addresses remain.</p>
<h2>Health checks</h2><table><tr><th>Check</th><th>Result</th><th>Evidence</th></tr>{{range .Health}}<tr><td>{{.Name}}</td><td>{{if .OK}}OK{{else}}ATTENTION{{end}}</td><td>{{.Detail}}</td></tr>{{end}}</table>
<h2>Decoy inventory</h2><table><tr><th>Name</th><th>Status</th><th>Locations</th></tr>{{range .Baits}}<tr><td>{{.Name}}<br><small>{{.Kind}}</small></td><td>{{.Status}}<br>{{.Note}}</td><td>{{range .Paths}}<code>{{.}}</code><br>{{end}}</td></tr>{{end}}</table>
<h2>Recent detections ({{len .Alerts}})</h2>{{range .Alerts}}<article class="card {{.Tier}}"><h3>{{.Title}}</h3><span class="badge">{{.Tier}} · {{.Status}}{{if .Test}} · SAFE TEST{{end}}</span><p>{{.Time.Format "2006-01-02 15:04:05 MST"}} · {{.ID}}</p><p>{{.Summary}}</p><ul>{{range .Verdict.Reasons}}<li>{{.}}</li>{{end}}</ul>{{with .Process}}<p><b>Reader:</b> <code>{{.Image}}</code> · PID {{.PID}}{{if .Exited}} (exited / historical){{end}}<br><b>SHA-256:</b> <code>{{.SHA256}}</code><br><b>Publisher:</b> {{.Signature.Signer}} · Signature valid: {{.Signature.Valid}}</p>{{if .CommandLine}}<pre>{{.CommandLine}}</pre>{{end}}{{if .Parents}}<p><b>Parent processes</b></p><ul>{{range .Parents}}<li>{{.PID}} <code>{{.Image}}</code>{{if .CommandLine}}<pre>{{.CommandLine}}</pre>{{end}}</li>{{end}}</ul>{{end}}{{if .Connections}}<p><b>Observed connections</b></p><ul>{{range .Connections}}<li>{{.Proto}} · {{.Local}} → {{.Remote}} · {{.State}}</li>{{end}}</ul>{{end}}{{end}}<p><b>Decoys accessed</b></p><ul>{{range .Baits}}<li>{{.Access}} · <code>{{.Path}}</code></li>{{end}}</ul><p><b>Actions</b></p><ul>{{range .Actions}}<li>{{.Action}}: {{if .OK}}succeeded{{else}}FAILED{{end}} · {{.Detail}}</li>{{else}}<li>Evidence recorded; no containment action.</li>{{end}}</ul><small>{{if .Instant}}Oplock inference{{else}}Audit event{{end}} · Response latency {{.LatencyMS}} ms · {{.Note}}</small></article>{{else}}<div class="card">No detections in this report. This is not proof that the system is malware-free.</div>{{end}}
<p class="sub">sentient1 · Built on the MIT-licensed ABA engine. Report generated locally; no scripts, remote resources or telemetry.</p></main></html>`))

func WriteHTML(w io.Writer, d Snapshot) error { return report.Execute(w, d) }
